import pandas as pd
import numpy as np

class SimpleFeatureStore:
    def __init__(self):
        self.offline_store = {}
        self.online_store = {}

    def compute_and_store(self, user_id, transactions_df):
        avg_purchase_30d = transactions_df["amount"].tail(30).mean()
        self.offline_store.setdefault(user_id, []).append(avg_purchase_30d)
        self.online_store[user_id] = avg_purchase_30d  # latest value, for low-latency lookup
        return avg_purchase_30d

    def get_for_training(self, user_id):
        return self.offline_store.get(user_id, [])

    def get_for_serving(self, user_id):
        return self.online_store.get(user_id)

store = SimpleFeatureStore()

rng = np.random.RandomState(42)
transactions = pd.DataFrame({"amount": rng.uniform(10, 200, size=50)})
computed_value = store.compute_and_store(user_id=123, transactions_df=transactions)

print(f"Computed once: {computed_value:.2f}")
print(f"Training reads: {store.get_for_training(123)}")
print(f"Real-time serving reads: {store.get_for_serving(123):.2f}")
print("\nBoth paths draw from the same single computation, structurally eliminating train-serve skew")
